import gi
gi.require_version('Gtk', '3.0')
from gi.repository import Gtk

from .basic import GtkAdapter

class EntryAdapter(GtkAdapter):
    """
        An adapter for a Gtk.Entry widget.

        Commits on focus-out and Enter rather than on every keystroke, so
        per-character writes don't hammer expensive property side-effects
        (e.g. plot redraws on marker.label).
    """
    widget_types = ["entry", "input"]
    _check_widget_type = Gtk.Entry

    _wid_read = lambda c, w: Gtk.Entry.get_text(w)
    _wid_write = lambda c, w, v: Gtk.Entry.set_text(w, str(v))
    _signal = "focus-out-event"

    def _connect_widget(self):
        super(EntryAdapter, self)._connect_widget()
        # Also commit when the user presses Enter.
        self._activate_signal_id = self._widget.connect(
            "activate", self._on_wid_changed, self._signal_args
        )

    def _disconnect_widget(self, widget=None):
        if getattr(self, "_activate_signal_id", None) is not None:
            try:
                (widget or self._widget).disconnect(self._activate_signal_id)
            except Exception:
                pass
            self._activate_signal_id = None
        super(EntryAdapter, self)._disconnect_widget(widget=widget)

    pass # end of class
